{
  "name": "resolve-real-path",
  "version": "1.0.0",
  "description": "Resolve symlinks in a file path to its real, canonical filesystem path.",
  "type": "module",
  "main": "src/index.js",
  "bin": {
    "resolve-real-path": "bin/cli.js"
  },
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "src",
    "bin"
  ],
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "engines": {
    "node": ">=14.18.0"
  },
  "license": "MIT"
}

import { realpath as realpathCallback } from "node:fs";
import { realpath as realpathPromise } from "node:fs/promises";
import { promisify } from "node:util";

const realpathAsync = promisify(realpathCallback);

export function resolveRealPath(inputPath, options) {
  return realpathAsync(inputPath, options);
}

export function resolveRealPathSync(inputPath, options) {
  return realpathCallback.native
    ? realpathCallback(inputPath, options)
    : realpathCallback(inputPath, options);
}

export function resolveRealPathPromise(inputPath, options) {
  return realpathPromise(inputPath, options);
}

export default resolveRealPath;

import { realpathSync } from "node:fs";
import { realpath as realpathAsync } from "node:fs/promises";

export function resolveRealPath(inputPath, options) {
  return realpathAsync(inputPath, options);
}

export function resolveRealPathSync(inputPath, options) {
  return realpathSync(inputPath, options);
}

export default resolveRealPath;

#!/usr/bin/env node
import { resolveRealPath } from "../src/index.js";

const paths = process.argv.slice(2);

if (paths.length === 0) {
  console.error("Usage: resolve-real-path <path> [path...]");
  process.exit(1);
}

let failed = false;

for (const inputPath of paths) {
  try {
    const resolved = await resolveRealPath(inputPath);
    console.log(resolved);
  } catch (error) {
    failed = true;
    console.error(`${inputPath}: ${error.message}`);
  }
}

process.exit(failed ? 1 : 0);

import test from "node:test";
import assert from "node:assert/strict";
import { mkdtemp, mkdir, symlink, writeFile } from "node:fs/promises";
import { realpathSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { resolveRealPath, resolveRealPathSync } from "../src/index.js";

test("resolves a symlinked file to its target", async () => {
  const dir = await mkdtemp(join(tmpdir(), "realpath-"));
  const target = join(dir, "target.txt");
  const link = join(dir, "link.txt");
  await writeFile(target, "hello");
  await symlink(target, link);

  assert.equal(await resolveRealPath(link), await resolveRealPath(target));
  assert.equal(resolveRealPathSync(link), realpathSync(target));
});

test("resolves symlinked directories", async () => {
  const dir = await mkdtemp(join(tmpdir(), "realpath-"));
  const targetDir = join(dir, "real");
  const linkDir = join(dir, "link");
  await mkdir(targetDir);
  await symlink(targetDir, linkDir);

  assert.equal(await resolveRealPath(linkDir), await resolveRealPath(targetDir));
});

test("rejects on missing paths", async () => {
  await assert.rejects(resolveRealPath("/no/such/path/here"));
});

